  const fonts={inherit:'var(--font-interface,system-ui)',sans:'system-ui,sans-serif',serif:'Georgia,serif',mono:'var(--font-monospace,monospace)'};root.style.setProperty('--kf-font-family',fonts[p.fontFamily]);
