  if(meta.kind!=='source'){kbRefs(meta.sourceRefs);kbList(meta.tags||[],30).forEach(v=>kbText(v,60));kbList(meta.related||[],50).forEach(v=>kbText(v,100));if(meta.userNotes!==undefined)kbText(meta.userNotes);}
