async function aiRead(plugin){const raw=await kbReadCurrent(plugin,AI_PATH);if(raw===null)return {raw,state:{knowledgeflowAI:1,vault:await kbVaultIdentity(plugin),seq:0,paused:true,config:aiConfig(),jobs:[]}};if(raw.length>8000000)throw Error('AI queue size limit exceeded');return {raw,state:await aiValidate(plugin,await kbUnseal(raw))};}
