function aiSetKey(plugin,value){if(typeof value!=='string'||!/^[A-Za-z0-9_-]{16,512}$/.test(value))throw Error(kl('API-Schlüssel prüfen.','Check API key.'));aiSecrets.set(plugin,value);}
