function kbRediscoveryAfterV1(record,op,day,key,at){if(!['important','later','hide','restore','reviewed'].includes(op)||!validDay(day))throw Error('Invalid rediscovery action');const s=kbRediscoveryState(record.meta);if(op==='important')s.important=!s.important;if(op==='later')s.nextReview=kbRediscoveryDay(day,7);if(op==='hide')s.hidden=true;if(op==='restore'){s.hidden=false;s.nextReview=day;}if(op==='reviewed'){s.lastReviewed=day;s.nextReview=kbRediscoveryDay(day,s.important?14:30);}s.actionKey=key;s.actionAt=at;return encode({...record.meta,rediscovery:s},record.body);}
async function kbRediscoveryReport(plugin,{day=today(),mode='due',project=''}={}){if(!validDay(day)||!['due','all','hidden'].includes(mode)||typeof project!=='string'||project.length>100)throw Error('Invalid rediscovery filter');const index=await kbHubIndex(plugin),items=[],invalid=[];for(const row of index.rows){if(row.meta.kind==='source'||project&&row.meta.project!==project)continue;try{const state=kbRediscoveryState(row.meta),due=!state.hidden&&(!state.nextReview||state.nextReview<=day);if(mode==='due'&&!due||mode==='hidden'&&!state.hidden||mode==='all'&&state.hidden)continue;const origin=state.lastReviewed||kbWeekDay(row.meta.created),age=origin?Math.max(0,Math.floor((Date.parse(day+'T12:00:00Z')-Date.parse(origin+'T12:00:00Z'))/86400000)):0;items.push({row,state,due,age,score:age+(state.important?14:0),reason:(state.important?kl('Als wichtig markiert · ','Marked important · '):'')+(state.lastReviewed?kl('Zuletzt bestätigt: ','Last confirmed: ')+state.lastReviewed:kl('Noch nicht in Wiederentdecken bestätigt','Not yet confirmed in Rediscover'))+(state.nextReview?kl(' · Wieder ab ',' · Due from ')+state.nextReview:'')});}catch(e){invalid.push({path:row.file.path,error:e.message});}}items.sort((a,b)=>b.score-a.score||a.row.file.path.localeCompare(b.row.file.path));return {index,day,mode,project,items,invalid};}
async function kbValidateRediscoveryPlan(plugin,plan){const a=plan.rediscoveryApproval,records=plan.writes.filter(w=>w.role==='record');if(!a||a.version!==1||records.length!==1||plan.writes.length!==3||plan.reads.length||!validDay(a.day))throw Error('Invalid rediscovery plan');const w=records[0];if(w.path!==a.path||!kbSafeWritePath(w.path)||!w.path.startsWith(KB_ROOT+'/Seiten/')||typeof w.before!=='string')throw Error('Invalid rediscovery target');const record={file:{path:w.path},raw:w.before,...kbDecode(w.before)};if(record.meta.state!=='published'||record.meta.kind==='source'||record.meta.quickNote!==undefined||a.key!==await kbHash((await kbHash(w.before))+':'+a.op+':'+a.day)||w.after!==kbRediscoveryAfterV1(record,a.op,a.day,a.key,plan.created))throw Error('Rediscovery plan exceeds approved change');const history=plan.writes.filter(w=>w.role==='history'),audit=plan.writes.filter(w=>w.role==='audit');if(history.length!==1||audit.length!==1||history[0].before!==null||audit[0].before!==null)throw Error('Invalid rediscovery history');const old=decodeHistory(history[0].after);if(old.body!==w.before||old.meta.recordPath!==w.path||old.meta.transactionId!==plan.id)throw Error('Invalid rediscovery snapshot');}
async function kbRediscoveryAction(plugin,report,item,op){report=structuredClone({day:report.day,index:{pins:report.index.pins}});item=structuredClone(item);return plugin.kbQueue(async()=>{try{return await kbWriteSerial(plugin,async()=>{const journal=await plugin.kbJournalScan();if(journal.invalid.length||journal.pending.length)throw Error(kl('Zuerst offene Änderungen im Änderungsprotokoll prüfen.','Review pending changes in the change log first.'));const original={file:item?.row?.file,raw:item?.row?.raw,...kbDecode(item?.row?.raw)},day=report.day;if(!kbLinkTarget(original)||!report.index.pins.some(p=>p.path===original.file.path&&p.raw===original.raw))throw Error('Not a rediscovery note');const key=await kbHash((await kbHash(original.raw))+':'+op+':'+day),raw=await kbReadCurrent(plugin,original.file.path);if(raw===null)throw Error('Note missing');const current=kbDecode(raw),s=kbRediscoveryState(current.meta);if(s.actionKey===key&&raw===kbRediscoveryAfterV1(original,op,day,key,s.actionAt))return {duplicate:true};await plugin.kbFresh();if(raw!==original.raw||!kbAskSameCorpus(report.index,plugin.knowledge||[]))throw Error(kl('Bestand geändert. Wiederentdecken neu laden.','Collection changed. Reload Rediscover.'));const id=crypto.randomUUID(),created=new Date().toISOString(),after=kbRediscoveryAfterV1(original,op,day,key,created),writes=[{path:original.file.path,before:raw,after,role:'record'},{path:KB_ROOT+'/Verlauf/'+crypto.randomUUID()+'.md',before:null,after:encode({knowledgeflowHistory:1,recordPath:original.file.path,transactionId:id,created},raw),role:'history'},{path:KB_ROOT+'/Protokoll/'+id+'.md',before:null,after:'# KnowledgeFlow · rediscovery\n\n'+created+'\n\n'+op+'\n',role:'audit'}];for(const w of writes){w.beforeHash=w.before===null?null:await kbHash(w.before);w.afterHash=await kbHash(w.after);}const plan={knowledgeflowTransaction:1,id,root:KB_ROOT,vault:await kbVaultIdentity(plugin),action:'rediscovery',created,reads:[],rediscoveryApproval:{version:1,path:original.file.path,op,day,key},writes},path=KB_JOURNAL+'/'+id+'.md';await kbValidatePlan(plugin,plan,path);const sealed=await kbSeal(plan);if(sealed.length>16000000)throw Error('Rediscovery operation too large');await plugin.kbFolder(KB_JOURNAL);try{await plugin.app.vault.create(path,sealed);await kbApplyTransaction(plugin,await kbInspectTransaction(plugin,id));}catch(e){try{if(await kbReceipt(plugin,await kbReadJournal(plugin,path)))return {duplicate:false};}catch(_){}throw Error(kl('Änderung unterbrochen. Im Änderungsprotokoll prüfen. ','Change interrupted. Review change log. ')+e.message);}return {duplicate:false};});}finally{await plugin.kbRefreshViews();}});}
function renderRediscovery(view,parent){const c=parent.createEl('section',{cls:'kf-rediscovery'}),generation=(view.rediscoveryGeneration||0)+1;view.rediscoveryGeneration=generation;c.createEl('h2',{text:kl('Wiederentdecken','Rediscover')});c.createEl('p',{text:kl('Wichtige und länger nicht bestätigte Notizen wieder ansehen. Die Auswahl aktualisiert sich täglich und bei Bestandsänderungen. Erst deine Schaltflächen speichern Rückmeldungen.','Revisit important notes and those not confirmed recently. Selection refreshes daily and with collection changes. Only your buttons save feedback.'),cls:'kf-muted'});const status=c.createEl('p',{text:kl('Notizen zusammenstellen …','Preparing notes …'),attr:{role:'status'}});(async()=>{try{const report=await view.plugin.kbRediscoveryReport({mode:view.rediscoveryMode||'due',project:view.rediscoveryProject||''});if(!c.isConnected||view.closed||generation!==view.rediscoveryGeneration)return;status.setText(report.items.length+kl(' passende Notizen · ',' matching notes · ')+report.day);const controls=c.createDiv({cls:'kf-kb-toolbar'}),mode=controls.createEl('select',{attr:{'aria-label':kl('Wiederentdeckungsansicht','Rediscovery view')}});for(const [value,text]of [['due',kl('Jetzt wiederentdecken','Rediscover now')],['all',kl('Alle sichtbaren Notizen','All visible notes')],['hidden',kl('Ausgeblendete Notizen','Hidden notes')]])mode.createEl('option',{value,text});mode.value=report.mode;mode.onchange=()=>{view.rediscoveryMode=mode.value;view.rediscoveryLimit=6;view.render();};const project=controls.createEl('select',{attr:{'aria-label':kl('Wiederentdecken-Projektfilter','Rediscovery project filter')}});project.createEl('option',{value:'',text:kl('Alle Projekte','All projects')});for(const id of [...new Set([...projects(view.plugin.settings).map(p=>p.id),...report.index.rows.map(r=>r.meta.project).filter(v=>typeof v==='string'&&v)])])project.createEl('option',{value:id,text:projects(view.plugin.settings).find(p=>p.id===id)?.name||id});project.value=report.project;project.onchange=()=>{view.rediscoveryProject=project.value;view.rediscoveryLimit=6;view.render();};button(controls,kl('Neu zusammenstellen','Refresh selection'),()=>view.plugin.kbRefreshViews().catch(e=>status.setText(e.message)),'kf-text-button');c.createEl('p',{text:kl('Reihenfolge: vergangene Tage seit deiner Bestätigung, sonst seit Erstellung; wichtige Notizen erhalten einen Vorsprung von 14 Tagen. Keine globale Lesehistorie und kein Lernerfolg-Nachweis.','Order: elapsed days since confirmation, otherwise creation; important notes receive a 14-day boost. No global reading history or learning assessment.'),cls:'kf-muted'});if(report.invalid.length||report.index.excluded.length||(view.plugin.knowledgeInvalid||[]).length||Object.values(report.index.limits).some(Boolean))c.createEl('p',{text:kl('Einige Dateien sind ungültig oder außerhalb der begrenzten Prüfung (500 Einträge / 4 Mio. Zeichen). Änderungsprotokoll und Themenzentralen zeigen weitere Hinweise.','Some files are invalid or outside bounded checks (500 records / 4M characters). Change log and Topic hubs provide details.'),attr:{role:'alert'}});if(!report.items.length)c.createEl('p',{text:kl('Aktuell keine passenden Notizen. Unter „Alle sichtbaren Notizen“ kannst du Wichtigkeit und Wiedervorlage verwalten.','No matching notes now. Manage importance and review dates under All visible notes.')});const grid=c.createDiv({cls:'kf-hub-groups'});for(const item of report.items.slice(0,view.rediscoveryLimit||6)){const card=grid.createEl('article',{cls:'kf-hub-card'});card.createEl('h3',{text:item.row.meta.title});card.createEl('p',{text:item.reason,cls:'kf-muted'});card.createEl('blockquote',{text:kbHubExcerpt(item.row).text});const error=card.createDiv({attr:{role:'alert'}}),actions=card.createDiv({cls:'kf-kb-actions'});button(actions,kl('Notiz öffnen','Open note'),async()=>{try{const fresh=await kbVerifyHubEvidence(view.plugin,report.index,kbHubExcerpt(item.row));await view.plugin.app.workspace.getLeaf(true).openFile(fresh.file);}catch(e){error.setText(e.message);}},'kf-text-button');const add=(label,op)=>button(actions,label,async()=>{const buttons=actions.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{await view.plugin.kbRediscoveryAction(report,item,op);}catch(e){error.setText(e.message);buttons.forEach(b=>b.disabled=false);}},'kf-text-button');add(item.state.important?kl('Wichtig entfernen','Remove importance'):kl('Als wichtig markieren','Mark important'),'important');if(item.state.hidden)add(kl('Wieder anzeigen','Show again'),'restore');else{add(kl('Gelesen · in ','Reviewed · in ')+(item.state.important?'14':'30')+kl(' Tagen',' days'),'reviewed');add(kl('In einer Woche','In one week'),'later');add(kl('Nicht erneut zeigen','Do not show again'),'hide');}}if(report.items.length>(view.rediscoveryLimit||6))button(c,kl('Weitere 6 zeigen','Show 6 more'),()=>{view.rediscoveryLimit=(view.rediscoveryLimit||6)+6;view.render();},'kf-text-button');}catch(e){if(c.isConnected&&generation===view.rediscoveryGeneration)status.setText(e.message);}})();}
